          axi_beat_woff <= 11'((hmao_araddr - TRAJ_BUFFER_BASE) >> 2);
      end
      if (ar_accepted) begin
        hmao_rvalid <= 1'b1;
        hmao_rlast  <= (hmao_arlen == 8'd0);
        hmao_rresp  <= 2'b00;
      end else if (hmao_rvalid && hmao_rready) begin
        if (hmao_rlast) begin
          hmao_rvalid <= 1'b0;
          hmao_rlast  <= 1'b0;
        end else begin
          axi_beat_woff <= axi_beat_woff + (axi_wm_wide ? 11'd8 : 11'd1);
